28	const BASE_PREMIUMS: Record<string, number> = {
29	  sword: 100,
30	  amulet: 60,
31	  staff: 80,
32	  potion: 40,
33	  rune: 25,
34	};
35	
36	const PROCESSING_FEE = 5;
37	
38	const PERCENT = 100;
39	
40	/**
41	 * Surcharges multiply before dividing, so the arithmetic stays exact.
42	 * A 1.1 multiplier would not: floating-point `100 * 1.1` is
43	 * 110.00000000000001, which rounds up to 111 and yields a 116 G premium
44	 * instead of 115 G.
45	 */
46	const addSurcharge = (amount: number, surchargePercent: number): number =>
47	  (amount * (PERCENT + surchargePercent)) / PERCENT;
48	
49	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
50	
51	const applyFirstInsuranceSurcharge = (amount: number): number =>
52	  addSurcharge(amount, FIRST_INSURANCE_SURCHARGE_PERCENT);
53	
54	/** All rounding is in the MHPCO's favor — always up. */
55	const roundInMHPCOsFavor = Math.ceil;
56	
57	const sumBasePremiums = (items: InsuredItem[]): number =>
58	  items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
59	
60	const quotePremium = (step: Step): QuoteResult => {
61	  const base = sumBasePremiums(step.items ?? []);
62	
63	  return {
64	    premium: roundInMHPCOsFavor(applyFirstInsuranceSurcharge(base)) +
65	      PROCESSING_FEE,
66	  };
67	};
68	
69	export const runScenario = (scenario: Scenario): ScenarioResults => ({
70	  results: scenario.steps.map(quotePremium),
71	});
